\item for $\mu $-almost all $x$, $y \mapsto f \left( \frac{d\kappa (x)}{d\eta (x)}(y) \right)$ is $\eta (x)$-integrable. 

\end{itemize}

Let $\mu , \nu $ be two finite measures on $\mathcal X$ and $\kappa , \eta : \mathcal X \rightsquigarrow \mathcal Y$ be two Markov kernels such that $\mu \otimes \kappa \ll \nu \otimes \eta $. Then $p \mapsto \log \frac{d \mu \otimes \kappa }{d \nu \otimes \eta }(p)$ is $\mu \otimes \kappa $-integrable if and only if the following hold: \begin{enumerate} \item $x \mapsto \log \frac{d \mu }{d \nu }(x)$ is $\mu $-integrable \label{:1} 

\item $x \mapsto \int _y \log \frac{d \kappa (x)}{d \eta (x)}(y) \partial \kappa (x)$ is $\mu $-integrable \label{:2} 

\item for $\mu $-almost all $x$, $y \mapsto \log \frac{d \kappa (x)}{d \eta (x)}(y)$ is $\kappa (x)$-integrable \label{:3} 

\end{enumerate}

